/* Exam workspace: question banks and exams stay isolated from every other route. */
(function(){
  const previous=window.coursePage;
  const style=document.createElement('style');
  style.textContent='.exam-page{display:grid;gap:16px;padding-bottom:24px}.exam-tabs{display:flex;gap:4px;border-bottom:1px solid var(--line)}.exam-tab{border:0;background:transparent;padding:10px 18px;color:var(--muted);font:600 13px system-ui;cursor:pointer;border-bottom:2px solid transparent}.exam-tab.active{color:#087c72;border-bottom-color:var(--mint)}.exam-toolbar{display:flex;justify-content:space-between;gap:12px;align-items:center;flex-wrap:wrap}.exam-toolbar h2{margin:0;font-size:18px}.exam-toolbar p{margin:4px 0 0;color:var(--muted);font-size:12px}.exam-actions{display:flex;gap:8px;flex-wrap:wrap}.exam-actions .btn{font-size:11px}.exam-stats{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.exam-stat{padding:14px 16px;border:1px solid var(--line);border-radius:12px;background:#fff}.exam-stat span,.exam-stat small{display:block;color:var(--muted);font-size:11px}.exam-stat strong{display:block;margin:5px 0;font-size:22px;color:var(--ink)}.exam-grid{display:grid;grid-template-columns:1.1fr .9fr;gap:14px}.exam-card{padding:18px;border:1px solid var(--line);border-radius:14px;background:#fff;box-shadow:var(--shadow)}.exam-card h3{margin:0;font-size:15px}.exam-card-head{display:flex;justify-content:space-between;align-items:flex-start;gap:8px;margin-bottom:12px}.exam-list{display:grid;gap:8px}.exam-row{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:12px;align-items:center;padding:12px;border:1px solid #e7f0ee;border-radius:10px}.exam-row b,.exam-row small{display:block}.exam-row small{margin-top:4px;color:var(--muted);font-size:11px}.exam-row-actions{display:flex;gap:6px}.exam-row-actions .btn{padding:6px 9px;font-size:10px}.exam-badge{display:inline-flex;padding:3px 7px;border-radius:99px;background:#eaf8f4;color:#087c72;font-size:10px}.exam-badge.warn{background:#fff4df;color:#9a6a29}.exam-upload{display:grid;grid-template-columns:1fr 1fr;gap:10px}.exam-upload-card{padding:16px;border:1px dashed #b9dcd5;border-radius:12px;background:#f8fdfc}.exam-upload-card h4{margin:0 0 5px;font-size:13px}.exam-upload-card p{margin:0 0 12px;color:var(--muted);font-size:11px;line-height:1.5}.exam-modal-bg{position:fixed;inset:0;z-index:80;background:rgba(24,54,79,.38);display:grid;place-items:center;padding:20px}.exam-modal{width:min(650px,100%);max-height:calc(100vh - 40px);overflow:auto;padding:22px;border-radius:16px;background:#fff;box-shadow:0 24px 70px rgba(24,54,79,.24)}.exam-modal-head{display:flex;justify-content:space-between;align-items:flex-start}.exam-modal-head h3{margin:0;font-size:18px}.exam-close{border:0;background:transparent;font-size:24px;color:var(--muted);cursor:pointer}.exam-stepper{display:flex;gap:6px;margin:16px 0}.exam-step{flex:1;padding:8px;border-radius:7px;background:#edf4f2;color:#718987;text-align:center;font-size:10px}.exam-step.active{background:#dff5ef;color:#087c72;font-weight:700}.exam-form{display:grid;gap:12px}.exam-form label{display:grid;gap:6px;color:#4d6d6d;font-size:11px}.exam-form input,.exam-form select,.exam-form textarea{width:100%;box-sizing:border-box;border:1px solid var(--line);border-radius:8px;padding:9px 10px;font:13px system-ui;color:var(--ink)}.exam-form textarea{min-height:90px;resize:vertical}.exam-checks{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.exam-checks label{display:flex;align-items:center;gap:6px;padding:9px;border:1px solid var(--line);border-radius:8px}.exam-modal-actions{display:flex;justify-content:flex-end;gap:8px;margin-top:16px;padding-top:14px;border-top:1px solid var(--line)}.exam-question{padding:14px;border:1px solid #e5efed;border-radius:10px;margin-bottom:9px}.exam-question b{display:block;line-height:1.5}.exam-question p{margin:7px 0 0;color:#577170;font-size:12px}.exam-question-meta{display:flex;gap:6px;margin-top:9px;flex-wrap:wrap}.exam-question-meta span{padding:3px 7px;border-radius:5px;background:#f0f7f5;color:#62807e;font-size:10px}@media(max-width:850px){.exam-grid{grid-template-columns:1fr}.exam-stats{grid-template-columns:repeat(2,1fr)}}@media(max-width:520px){.exam-upload{grid-template-columns:1fr}.exam-checks{grid-template-columns:1fr}.exam-toolbar{align-items:flex-start;flex-direction:column}.exam-actions{width:100%}.exam-actions .btn{flex:1}}';document.head.appendChild(style);
  const state={tab:'bank',banks:[{name:'离散数学基础题库',count:128,source:'教材解析 · v3',updated:'今天 10:24'},{name:'历年期中试题库',count:86,source:'历史试卷导入',updated:'昨天 16:10'}],questions:[{title:'设集合 A={1,2,3}，求其幂集的元素个数。',type:'选择题',difficulty:'基础',bank:'离散数学基础题库',answer:'8'},{title:'证明：任意有限无向图中，奇度顶点的个数为偶数。',type:'证明题',difficulty:'提高',bank:'离散数学基础题库',answer:'见解析'}],exams:[{name:'2026 秋季期中试卷',meta:'12 题 · 100 分 · 待审核',status:'待审核'},{name:'第 2 次单元测验',meta:'8 题 · 50 分 · v3',status:'已发布'}]};
  const esc=s=>String(s).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
  const fileInput=(id,accept)=>`<input id="${id}" type="file" accept="${accept}" hidden onchange="examHandleUpload(this)">`;
  function page(){const bank=state.tab==='bank';return `<div class="exam-page"><div class="eyebrow">试卷管理 / EXAM</div><div class="title-row"><div><h1>试卷管理</h1><p class="muted">题库与试卷统一管理，支持素材解析、AI 出题和智能组卷</p></div></div><div class="exam-tabs"><button class="exam-tab ${bank?'active':''}" onclick="examSwitch('bank')">题库</button><button class="exam-tab ${!bank?'active':''}" onclick="examSwitch('exam')">试卷</button></div>${bank?bankPage():examPage()}</div>`}
  function bankPage(){return `<div class="exam-toolbar"><div><h2>题库工作台</h2><p>创建题库、导入历史素材，或基于课程资料生成新题目</p></div><div class="exam-actions"><button class="btn secondary" onclick="examNewBank()">＋ 创建题库</button><button class="btn secondary" onclick="examOpen('素材上传')">上传题库素材</button><button class="btn primary" onclick="examOpen('AI 生成题目')">AI 生成题目</button></div></div><div class="exam-stats"><div class="exam-stat"><span>题库数量</span><strong>${state.banks.length}</strong><small>当前课程</small></div><div class="exam-stat"><span>题目总数</span><strong>${state.questions.length+212}</strong><small>含已确认题目</small></div><div class="exam-stat"><span>待确认解析</span><strong>6</strong><small>来自 2 个文件</small></div><div class="exam-stat"><span>知识点覆盖</span><strong>92%</strong><small>v3 课程大纲</small></div></div><div class="exam-grid"><section class="exam-card"><div class="exam-card-head"><h3>我的题库</h3><span class="exam-badge">可维护</span></div><div class="exam-list">${state.banks.map((b,i)=>`<div class="exam-row"><div><b>${esc(b.name)}</b><small>${b.count} 道题 · ${esc(b.source)} · 更新于 ${b.updated}</small></div><div class="exam-row-actions"><button class="btn secondary" onclick="examPreviewBank(${i})">预览题目</button><button class="btn secondary" onclick="examOpen('题库设置')">管理</button></div></div>`).join('')}</div></section><section class="exam-card"><div class="exam-card-head"><h3>题目预览</h3><span class="exam-badge">最近入库</span></div>${state.questions.slice(0,2).map((q,i)=>`<article class="exam-question"><b>${i+1}. ${esc(q.title)}</b><p>答案：${esc(q.answer)}</p><div class="exam-question-meta"><span>${q.type}</span><span>${q.difficulty}</span><span>${q.bank}</span></div></article>`).join('')}</section></div><section class="exam-card"><div class="exam-card-head"><div><h3>添加题库素材</h3><small class="muted">上传试卷、题目文档，AI 解析后由老师确认再导入</small></div></div><div class="exam-upload"><div class="exam-upload-card"><h4>题库素材上传</h4><p>支持 Word、PDF、Excel、图片；自动识别题干、选项、答案和解析。</p><button class="btn secondary" onclick="document.getElementById('examBankFile').click()">选择文件</button>${fileInput('examBankFile','.doc,.docx,.pdf,.xls,.xlsx,.png,.jpg')}</div><div class="exam-upload-card"><h4>AI 生成题目</h4><p>上传教材、课件或资料，解析知识点后配置题型、难度和数量。</p><button class="btn primary" onclick="examOpen('AI 生成题目')">开始配置</button></div></div></section>`}
  function examPage(){return `<div class="exam-toolbar"><div><h2>试卷工作台</h2><p>管理已有试卷、解析上传试卷，或按规则智能组卷</p></div><div class="exam-actions"><button class="btn secondary" onclick="examOpen('上传已有试卷')">上传已有试卷</button><button class="btn primary" onclick="examOpen('AI 智能组卷')">AI 智能组卷</button></div></div><div class="exam-stats"><div class="exam-stat"><span>试卷总数</span><strong>${state.exams.length}</strong><small>当前课程</small></div><div class="exam-stat"><span>待审核</span><strong>1</strong><small>教学秘书审核</small></div><div class="exam-stat"><span>已发布</span><strong>1</strong><small>当前有效版本</small></div><div class="exam-stat"><span>可导出</span><strong>1</strong><small>正式版本</small></div></div><section class="exam-card"><div class="exam-card-head"><h3>已有试卷</h3><span class="exam-badge">共 ${state.exams.length} 份</span></div><div class="exam-list">${state.exams.map((e,i)=>`<div class="exam-row"><div><b>${esc(e.name)} <span class="exam-badge ${e.status==='待审核'?'warn':''}">${e.status}</span></b><small>${e.meta}</small></div><div class="exam-row-actions"><button class="btn secondary" onclick="examPreviewExam(${i})">预览</button><button class="btn secondary" onclick="examExport('${esc(e.name)}','PDF')">下载 PDF</button><button class="btn secondary" onclick="examExport('${esc(e.name)}','Word')">Word</button></div></div>`).join('')}</div></section><section class="exam-card"><div class="exam-card-head"><div><h3>试卷操作</h3><small class="muted">上传解析的题目可选择性导入题库，再继续编辑试卷</small></div></div><div class="exam-upload"><div class="exam-upload-card"><h4>上传已有试卷</h4><p>解析试卷结构、分值和题目；解析完成后可勾选题目入库。</p><button class="btn secondary" onclick="document.getElementById('examPaperFile').click()">上传并解析</button>${fileInput('examPaperFile','.doc,.docx,.pdf,.png,.jpg')}</div><div class="exam-upload-card"><h4>AI 智能组卷</h4><p>配置题型、分数、难度和数量，AI 按课程知识点规则生成试卷。</p><button class="btn primary" onclick="examOpen('AI 智能组卷')">配置组卷规则</button></div></div></section>`}
  function close(){document.querySelector('.exam-modal-bg')?.remove()}
  function modal(title){const gen=title==='AI 生成题目',compose=title==='AI 智能组卷',upload=title==='素材上传'||title==='上传已有试卷';let body='';if(gen)body='<div class="exam-stepper"><span class="exam-step active">1 上传资料</span><span class="exam-step">2 核对知识点</span><span class="exam-step">3 配置规则</span><span class="exam-step">4 预览入库</span></div><div class="exam-form"><label>教材 / 课件 / 材料<input type="file" multiple accept=".pdf,.doc,.docx,.ppt,.pptx"></label><label>生成范围<select><option>第 1–3 章 · 全部知识点</option><option>仅图论与关系</option></select></label><div class="exam-checks"><label><input type="checkbox" checked>选择题</label><label><input type="checkbox" checked>填空题</label><label><input type="checkbox">证明题</label></div><label>题目数量<input type="number" value="10" min="1" max="50"></label><label>难度比例<select><option>基础 40% · 中等 40% · 提高 20%</option><option>基础 20% · 中等 50% · 提高 30%</option></select></label></div>';else if(compose)body='<div class="exam-stepper"><span class="exam-step active">1 组卷配置</span><span class="exam-step">2 AI 生成</span><span class="exam-step">3 预览调整</span><span class="exam-step">4 保存试卷</span></div><div class="exam-form"><label>试卷名称<input value="2026 秋季阶段测验"></label><label>考试范围<select><option>第 1–3 章 · 当前课程 v3</option><option>全课程</option></select></label><div class="exam-checks"><label><input type="checkbox" checked>选择题 × 8</label><label><input type="checkbox" checked>填空题 × 4</label><label><input type="checkbox" checked>证明题 × 2</label></div><label>总分<input type="number" value="100"></label><label>说明<textarea placeholder="补充组卷要求（可选）"></textarea></label></div>';else if(upload)body='<div class="exam-stepper"><span class="exam-step active">1 上传文件</span><span class="exam-step">2 AI 解析</span><span class="exam-step">3 核对并入库</span></div><div class="exam-form"><label>选择文件<input type="file" accept=".pdf,.doc,.docx,.png,.jpg"></label><p class="muted">系统将识别题目、题型、分值、答案和解析；解析结果会先进入待确认列表，不会直接入库。</p><label><input type="checkbox" checked>解析完成后打开题目确认</label></div>';else body='<div class="exam-form"><label>题库名称<input value="新建题库"></label><label>描述<textarea placeholder="说明题库用途和来源"></textarea></label></div>';document.body.insertAdjacentHTML('beforeend',`<div class="exam-modal-bg"><div class="exam-modal" role="dialog" aria-modal="true"><div class="exam-modal-head"><h3>${title}</h3><button class="exam-close" onclick="examClose()" aria-label="关闭">×</button></div>${body}<div class="exam-modal-actions"><button class="btn secondary" onclick="examClose()">取消</button><button class="btn primary" onclick="examSubmit('${title}')">${gen?'开始解析并生成':compose?'生成试卷':upload?'开始解析':'创建题库'}</button></div></div></div>`)}
  window.examSwitch=k=>{state.tab=k;document.getElementById('app').innerHTML=page()};window.examOpen=modal;window.examClose=close;window.examNewBank=()=>modal('创建题库');window.examHandleUpload=input=>{if(input.files?.length){alert(`已选择 ${input.files.length} 个文件，进入 AI 解析确认流程`);input.value=''}};window.examSubmit=title=>{close();alert(title==='AI 智能组卷'?'已生成试卷草稿，可在列表中预览和调整':'已提交 AI 解析任务，完成后将在待确认列表中展示')};window.examPreviewBank=i=>alert(`${state.banks[i].name}\n\n题目预览将在此展开，可按题型、难度和知识点筛选。`);window.examPreviewExam=i=>alert(`${state.exams[i].name}\n\n试卷预览：题目、分值、答案与评分标准可分别查看。`);window.examExport=(name,type)=>alert(`${name}\n已生成 ${type} 导出任务`);
  function tidy(){
    const root=document.querySelector('.exam-page');if(!root)return;
    root.querySelector('.eyebrow')?.remove();
    root.querySelector('.title-row')?.remove();
    const tabs=[...root.querySelectorAll('.exam-tab')];
    tabs.sort((a,b)=>a.textContent==='试卷'?-1:b.textContent==='试卷'?1:0).forEach(x=>root.querySelector('.exam-tabs').appendChild(x));
    const removeCard=label=>[...root.querySelectorAll('.exam-card')].find(card=>card.querySelector('h3')?.textContent.trim()===label)?.remove();
    root.querySelectorAll('.exam-row-actions .btn').forEach(btn=>{if(btn.textContent.trim()==='管理')btn.textContent='编辑'});
    if(state.tab==='bank'){removeCard('题目预览');removeCard('添加题库素材');const grid=root.querySelector('.exam-grid');if(grid)grid.style.gridTemplateColumns='1fr';const list=[...root.querySelectorAll('.exam-card')].find(card=>card.querySelector('h3')?.textContent.trim()==='我的题库')?.querySelector('.exam-list');if(list){list.classList.add('exam-bank-cards');list.style.display='grid';list.style.gridTemplateColumns='repeat(auto-fit,minmax(240px,1fr))';list.querySelectorAll('.exam-row').forEach(row=>{row.style.display='block';row.style.padding='16px';row.querySelector('.exam-row-actions').style.marginTop='12px'})}}else removeCard('试卷操作');
  }
  const renderExam=()=>{const html=(window.__courseShellV2||window.shell)(page(),'exam');setTimeout(tidy,0);return html};
  state.tab='exam';
  const openBank=window.examNewBank;window.examNewBank=()=>{openBank();setTimeout(()=>{const m=document.querySelector('.exam-modal');if(!m)return;const h=m.querySelector('h3');if(h)h.textContent='新建题目目录';const label=m.querySelector('label');if(label)label.insertAdjacentHTML('afterend','<p class="muted">目录创建后，可在其中持续录入和维护题目。</p>');const submit=m.querySelector('.exam-modal-actions .primary');if(submit)submit.textContent='创建目录'},0)};
  const submitExam=window.examSubmit;window.examSubmit=title=>{if(title==='创建题库'){const input=document.querySelector('.exam-modal input');const name=input?.value.trim()||'未命名题目目录';state.banks.push({name,count:0,source:'手动创建',updated:'刚刚'});state.tab='bank';close();render();alert(`已创建题目目录“${name}”，可继续录入题目`);return}submitExam(title)};
  const switchExam=window.examSwitch;window.examSwitch=k=>{switchExam(k);render();setTimeout(tidy,0)};
  window.coursePage=function(k){if(k==='exam')return renderExam();return previous(k)};coursePage=window.coursePage;if(location.hash==='#course/exam')render();
})();
